@extends('admin.layout') @section('heading',$category->exists?'Edit Category':'Add Category') @section('back_url', route('admin.categories.index')) @section('back_label','Categories') @section('content')<form class="panel" method="post" enctype="multipart/form-data" action="{{ $category->exists?route('admin.categories.update',$category):route('admin.categories.store') }}">@csrf @if($category->exists)@method('PUT')@endif<div class="grid2"><div class="field"><label>Name *</label><input name="name" value="{{ old('name',$category->name) }}" required></div><div class="field"><label>Slug</label><input name="slug" value="{{ old('slug',$category->slug) }}"><span class="hint">Leave blank to generate automatically.</span></div><div class="field full"><label>Description</label><textarea name="description">{{ old('description',$category->description) }}</textarea></div><div class="field"><label>Image</label><input type="file" name="image" accept="image/*">@if($category->image)<img class="thumb" src="{{ \App\Support\MediaUrl::make($category->image) }}">@endif</div><div class="field"><label>Sort Order</label><input type="number" name="sort_order" value="{{ old('sort_order',$category->sort_order??0) }}"></div><div class="field"><label>SEO Title</label><input name="seo_title" value="{{ old('seo_title',$category->seo_title) }}"></div><div class="field"><label>SEO Description</label><textarea name="seo_description">{{ old('seo_description',$category->seo_description) }}</textarea></div><div class="field full"><label><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$category->exists?$category->is_active:true))> Active on website</label></div><div class="field full"><div class="actions"><button class="btn btn-primary">Save Category</button><a class="btn btn-outline" href="{{ route('admin.categories.index') }}">Cancel</a></div></div></div></form>@if($category->exists)<div class="panel danger-zone"><div><strong>Delete Category</strong><p>Categories can be deleted after all products have been moved or deleted.</p></div><form method="post" action="{{ route('admin.categories.destroy',$category) }}" onsubmit="return confirm('Delete this category?')">@csrf @method('DELETE')<button class="btn btn-danger">Delete Category</button></form></div>@endif@endsection